// th14_s3_w05 — TH14 v1.00b Stage 3 道中波次 5
// 源: st03.ecl.txt MainSub02 第二循环 587-600 (entry); GirlB01 149-159,
//     GirlB01_at 161-177, GirlB01_at2 179-226 (dependency).
// 卡帧 0 = MainSub02 循环入口; 开场 OPENING_BUFFER 后进入源排程, 源帧 f -> 卡帧 120+f.
// 弹型: 源 etSprite type 8/color 6 -> TH14_RICE(480) / 6 (见 th14/bullet-types.md).

const TH14_RICE: int = 480;
const TIME_LIMIT: int = 2800;
const OPENING_BUFFER: int = 120;

// GirlB01_at2 (源 179-226): 每敌一个 async 任务, 每轮 5 发自机狙米弹.
async sub girl_b01_at2() {
    // 源 182-199 的 etAngle/etSpeed 配置在首个 etOn 前即被 616 覆盖, 不发弹;
    // 持续有效的只有 etSprite(8,6)/etCount(1,1)/etAim(0)/etExSet(ANIM).
    var bursts: int = 32;          // 199: diffI($B,1,32,32,32)
    var gap: int = 20;             // 213-220: !LO 20 (Lunatic)
    var rank: int = global(GVAR_RANK);
    if rank == RANK_EASY {
        bursts = 1;                // Easy $B=1
        gap = 180;                 // !E 180
    } else if rank == RANK_NORMAL {
        gap = 60;                  // !N 60
    } else if rank == RANK_HARD {
        gap = 30;                  // !H 30
    }
    for b in 0..bursts {           // 202-224: 512 -> 844 loop, if($B--)
        for c in 0..5 {            // 203-212: $C=4, 5 发
            // 206: etAngle(0, %RANDRAD/64, 0.6981317); mode0 自机狙扇形 1 路,
            // 角 = A + RANDRAD/64; RANDRAD 为 [-pi,pi), 故 ±pi/64 = ±512 BAM, 每发抽一次.
            var spread: angle = (rand(1024) - 512) as angle;
            var a: angle = aim_player() + spread;
            // 207: etSpeed(0, %A, 0.0); %A 每轮重置 1.5, 每发 +0.2 (202,208)
            var sp: fx = 1.5fx + (c as fx) * 0.2fx;
            // 197: etExSet(0,0,0,2,1,...) type2=ANIM, a=1; 出生阶段省略但保留
            // position -= 4*velocity 的退位移 (见 th16/ex-effects.md).
            var back: fx = 4fx * sp;
            _ = fire(TH14_RICE, 6,
                     $self_x - back * cos(a),
                     $self_y - back * sin(a),
                     sp, a, none, none);
            wait(1);               // 210
        }
        wait(gap);                 // 213-222: 难度等待
    }
}

// GirlB01_at (源 161-177): 入场减速转向, 60 帧后启动 at2, 再 120 帧后低速飘离.
async sub girl_b01() {
    set_invuln(65535);             // 训练外壳: 真实敌无敌, 体碰按源保留
    set_hurtbox(12fx);             // 163: setHurtbox(24,24) 圆形分支 24*0.5
    set_hitbox(8fx);               // 164: setHitbox(16,16) 圆形分支 16*0.5
    move_vel(0, 90deg, 3fx, EASE_LINEAR);        // 165: moveVel(pi/2, 3)
    move_vel(60, 78.75deg, 0fx, EASE_QUAD_IN);   // 166: moveVelTime(60,1,1.3744467,0)
    wait(60);                       // 167
    spawn girl_b01_at2();           // 168: @GirlB01_at2() async
    wait(120);                      // 169
    move_vel(60, 11.25deg, 1fx, EASE_LINEAR);    // 170: moveVelTime(60,0,0.19634955,1)
    loop { wait(1000); }            // 172-175: 自然离场
}

// MainSub02 587-600: $C=2, 每轮 4 只 GirlB01 (固定位置), 轮内 wait 30/50/50/50.
async sub pattern() {
    wait(OPENING_BUFFER);
    for it in 0..2 {                // 587,599: $C=2
        wait(30);                   // 590
        _ = spawn_enemy(-128fx, -32fx, 200, 0, 0, 0, girl_b01);  // 591
        wait(50);                   // 592
        _ = spawn_enemy(128fx, -32fx, 200, 0, 0, 0, girl_b01);   // 593 enmCreateM (镜像仅表现)
        wait(50);                   // 594
        _ = spawn_enemy(-32fx, -32fx, 200, 0, 0, 0, girl_b01);   // 595
        wait(50);                   // 596
        _ = spawn_enemy(32fx, -32fx, 200, 0, 0, 0, girl_b01);    // 597 enmCreateM
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
